def transform(grid):
    n = len(grid)
    starts = [0, 5, 10, 15]

    # Each small object is a 4x4 copy of the same pattern.
    pattern = None
    for r in starts:
        for c in starts:
            tile = [row[c:c+4] for row in grid[r:r+4]]
            if any(v == 2 for row in tile for v in row):
                pattern = [[1 if v == 2 else 0 for v in row] for row in tile]
                break
        if pattern is not None:
            break

    out = [[0 for _ in row] for row in grid]
    if pattern is None:
        return out

    # The pattern also specifies which positions in the 4x4 arrangement
    # contain copies of the object. Mark each copy at its arrangement coordinate.
    for tr, r in enumerate(starts):
        for tc, c in enumerate(starts):
            if pattern[tr][tc]:
                for i in range(4):
                    for j in range(4):
                        if pattern[i][j]:
                            out[r+i][c+j] = 2
                out[r+tr][c+tc] = 8

    return out
